80	/**
81	 * Ensure the three logbook records exist for an aircraft.
82	 * Creates them if they don't exist yet (lazy initialization).
83	 */
84	async function ensureLogbooks(equipmentId: string, flightSchoolId: string) {
85	  const types = ['airframe', 'engine', 'propeller'] as const;
86	  const existing = await db
87	    .select({ logbookType: schema.aircraftLogbooks.logbookType })
88	    .from(schema.aircraftLogbooks)
89	    .where(eq(schema.aircraftLogbooks.equipmentId, equipmentId));
90	
91	  const existingTypes = new Set(existing.map((r) => r.logbookType));
92	
93	  for (const t of types) {
94	    if (!existingTypes.has(t)) {
95	      await db.insert(schema.aircraftLogbooks).values({
96	        flightSchoolId,
97	        equipmentId,
98	        logbookType: t,
99	      });
100	    }
101	  }
102	}
