124	/**
125	 * Tenant isolation helper for entry-scoped endpoints.
126	 */
127	async function verifyEntryTenant(
128	  entryId: string,
129	  userOrgId: string | null,
130	): Promise<string | null> {
131	  const [entry] = await db
132	    .select({ logbookId: schema.aircraftLogbookEntries.logbookId })
133	    .from(schema.aircraftLogbookEntries)
134	    .where(eq(schema.aircraftLogbookEntries.id, entryId))
135	    .limit(1);
136	  if (!entry) return null;
137	  return verifyLogbookTenant(entry.logbookId, userOrgId);
138	}
